// vgsl-module: C:\Users\Victor\Desktop\hermes_work\vgpu-lab-hero\ds-hero-field.wgsl
// ============================================================================
// ds-hero-field.wgsl — световое поле первого экрана Discovery System
// Не «мутный шум», а структура: два слоя тонких светящихся нитей (flow field)
// с параллаксом + мягкий студийный конус света сверху + тёплый отблеск
// производственного яруса + курсорная подсветка + эллиптическая маска под
// зону заголовка + зерно 4%. Выход прозрачный: vec4f(col, 0.0).
// ============================================================================
struct _vgsl_2ed50e45__Params {
  time: f32,
  texel: vec2f,
  accent: vec3f,
  warm: vec3f,
  ink: vec3f,
  mouse: vec2f,
  aspect: f32,
  mask: f32,
  intensity: f32,
}

@group(0) @binding(0) var<uniform> params: _vgsl_2ed50e45__Params;

fn _vgsl_2ed50e45__hash21(p: vec2f) -> f32 {
  var q = fract(p * vec2f(123.34, 456.21));
  q = q + vec2f(dot(q, q + 45.32));
  return fract(q.x * q.y);
}

fn _vgsl_2ed50e45__valueNoise(p: vec2f) -> f32 {
  let i = floor(p);
  let f = fract(p);
  let u = f * f * (3.0 - 2.0 * f);
  let a = _vgsl_2ed50e45__hash21(i);
  let b = _vgsl_2ed50e45__hash21(i + vec2f(1.0, 0.0));
  let c = _vgsl_2ed50e45__hash21(i + vec2f(0.0, 1.0));
  let d = _vgsl_2ed50e45__hash21(i + vec2f(1.0, 1.0));
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

fn _vgsl_2ed50e45__fbm(p0: vec2f, oct: i32) -> f32 {
  var p = p0;
  var amp = 0.5;
  var sum = 0.0;
  for (var i = 0; i < 3; i = i + 1) {
    if (i >= oct) { break; }
    sum = sum + amp * _vgsl_2ed50e45__valueNoise(p);
    p = p * 2.07 + vec2f(17.1, 9.7);
    amp = amp * 0.5;
  }
  return sum;
}

// поле направления: медленно вращающиеся вихри
fn _vgsl_2ed50e45__flowAngle(p: vec2f, drift: f32) -> f32 {
  let n = _vgsl_2ed50e45__fbm(p * 0.42 + vec2f(drift, drift * 0.35), 3);
  return n * 6.28318 * 1.7 + drift * 0.35;
}

// нити: сдвигаем точку вдоль поля и берём тонкие изолинии fbm
fn _vgsl_2ed50e45__filaments(p: vec2f, scale: f32, lines: f32, warp: f32, drift: f32, w: f32) -> f32 {
  let a = _vgsl_2ed50e45__flowAngle(p * scale + vec2f(drift * 0.5, -drift * 0.3), drift);
  let moved = p + vec2f(cos(a), sin(a)) * warp;
  let n = _vgsl_2ed50e45__fbm(moved * scale + vec2f(0.0, drift * 0.6), 3);
  let band = abs(fract(n * lines) - 0.5) * 2.0;
  let line = smoothstep(0.92 - 0.55 * w, 0.0, band);
  let core = pow(line, 4.0);
  let halo = line * 0.10;
  return (core + halo) * (0.55 + 0.45 * n);
}

@fragment
fn fs_main(@location(0) uv: vec2f) -> @location(0) vec4f {
  let p = (uv - vec2f(0.5, 0.5)) * vec2f(params.aspect, 1.0);
  let t = params.time;

  var col = vec3f(0.0);

  // ---- слой 1: дальние нити, широкий ход, мята --------------------------
  let f1 = _vgsl_2ed50e45__filaments(p, 1.15, 22.0, 0.46, t * 0.020, 1.0);
  // ---- слой 2: ближние нити, плотнее и тоньше (параллакс) ---------------
  let f2 = _vgsl_2ed50e45__filaments(p, 2.35, 38.0, 0.22, t * 0.034, 1.35);
  // ---- слой 3: тёплый производственный отблеск, слева-внизу -------------
  let f3 = _vgsl_2ed50e45__filaments(p + vec2f(0.38, 0.32), 1.70, 18.0, 0.54, t * 0.026, 0.80);

  col = col + params.accent * f1 * 0.42;
  col = col + params.accent * f2 * 0.26;
  col = col + params.warm   * f3 * 0.26;

  // ---- студийный конус света сверху: дышит ------------------------------
  let cone = exp(-abs(p.x) * 1.35) * smoothstep(0.62, -0.62, p.y);
  let breathe = 0.88 + 0.12 * sin(t * 0.30);
  col = col + params.accent * cone * 0.045 * breathe;

  // ---- курсор: подхватывает свет ----------------------------------------
  let mp = (params.mouse - vec2f(0.5, 0.5)) * vec2f(params.aspect, 1.0);
  let dm = length(p - mp);
  col = col + params.accent * exp(-dm * 3.4) * 0.10
            + params.warm * exp(-dm * 5.6) * 0.035;

  // ---- маска под зону заголовка ----------------------------------------
  var guard = 1.0;
  if (params.mask > 0.5) {
    // горизонтальная полоса контента: поле живёт сверху и снизу, текст остаётся чистым
    let dy = (uv.y - 0.47) / 0.42;
    let band = exp(-dy * dy);
    // плюс мягкое ослабление в левой колонке (копирайт занимает её целиком)
    let dxL = max(0.0, (0.62 - uv.x) / 0.62);
    guard = 1.0 - 0.93 * band * (0.60 + 0.40 * dxL);
  }

  // ---- винетка ---------------------------------------------------------
  let vig = 1.0 - 0.55 * min(1.0, length(p * vec2f(0.86, 1.02)) * 1.25);

  // ---- зерно 4% (непрерывное, не по секундам) --------------------------
  let g = (_vgsl_2ed50e45__hash21(uv * 1024.0 + vec2f(fract(t * 11.3) * 41.0, fract(t * 7.7) * 29.0)) - 0.5) * 0.030;

  let out3 = (col * guard * vig + vec3f(g)) * params.intensity;
  return vec4f(out3, 0.0);
}
